import{_ as i,l,o as e,c as o,v as n,p as s,x as r,d as c,i as p,S as L}from"./chunks/framework.InCnrqk-.js";const E=JSON.parse('{"title":"LLaVA 原文","description":"","frontmatter":{"title":"LLaVA 原文","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/llava-paper.md","filePath":"llm/llava-paper.md","lastUpdated":1789023840000}'),A={name:"llm/llava-paper.md"};function h(u,a,d,C,P,V){const t=l("Mermaid");return e(),o("div",null,[a[1]||(a[1]=n('<h1 id="llava-原文" tabindex="-1">LLaVA 原文 <a class="header-anchor" href="#llava-原文" aria-label="Permalink to &quot;LLaVA 原文&quot;">​</a></h1><div class="epigraph"><p>用 GPT-4 把图的标题、框和类别转成多轮对话、细描述与复杂推理；再拿一层线性层把 CLIP patch 送进 Vicuna，冻结的语言模型就能开始谈图。</p><footer>—— Liu 等，Visual Instruction Tuning，NeurIPS 2023</footer></div><p>Liu、Li、Wu、Lee 的 LLaVA（Large Language-and-Vision Assistant）把视觉指令微调写成一条极简流水线：冻结的 <a href="/llm/radford-clip">CLIP</a> ViT-L/14 出 patch 特征，<strong>一层线性投影</strong>映到 Vicuna 词嵌入空间，与人类指令拼接后做因果语言建模。视觉指令数据不是手工标 15 万问答，而是把 COCO 图的标题、边界框、类别交给 <strong>GPT-4（纯文本）</strong>，生成三种监督：多轮对话、详细描述、复杂推理，合计约 <strong>158K</strong>。对齐阶段另用过滤后的 CC-595K 图文对只训投影。本篇按 arXiv:2304.08485 写初代；投影器的线性代数见 <a href="/llm/llava-projector">LLaVA 投影器</a>，1.5/1.6 的 MLP 与 AnyRes 见 <a href="/llm/llava-15">LLaVA-1.5 / 1.6</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>2023 年春，开源侧缺一种「像 ChatGPT 那样按用户指令谈图」的数据与架构。学术 VQA 是单轮短答案；<a href="/llm/flamingo">Flamingo</a> 是少样本开放生成但权重封闭、桥很重；<a href="/llm/blip2">BLIP-2</a> / <a href="/llm/instructblip">InstructBLIP</a> 走 Q-Former 瓶颈。若 CLIP 已经把视觉放到与语言可比较的空间，还要不要为了对齐再训一个 188M 的查询 Transformer？</p><p>数据问题同样硬。没有图的 GPT-4 不能看像素，但 COCO 已经提供了标题与框——足够让教师模型<strong>想象</strong>场景并写出「用户会问什么、助手该怎么答」。LLaVA 赌的是：这种合成指令 + 浅桥，就能把 Vicuna 的对话能力迁到视觉上，而不必十亿级图文对重训桥。</p><h3 id="教师是-gpt-4-学生是-vicuna-视觉是冻结-clip" tabindex="-1">教师是 GPT-4，学生是 Vicuna，视觉是冻结 CLIP <a class="header-anchor" href="#教师是-gpt-4-学生是-vicuna-视觉是冻结-clip" aria-label="Permalink to &quot;教师是 GPT-4，学生是 Vicuna，视觉是冻结 CLIP&quot;">​</a></h3><p>图像 \\(X_v\\) 经 CLIP 得 \\(Z_v=g(X_v)\\)，投影 \\(H_v=W\\cdot Z_v\\)，与 token 化指令拼进 Vicuna。训练两段：特征对齐只更新 \\(W\\)，数据为 CC-595K（从 CC3M 过滤到与 COCO 概念更近的子集）；视觉指令微调更新 \\(W\\) 与 LLM，数据为 158K 合成指令。ViT 全程冻结。输入分辨率 224，\\(P=14\\) 时 patch 数 256 量级（加 CLS 则 257），全部保留，不做 Q-Former 压缩。</p><p><span class="marginnote">GPT-4 当时的接口是纯文本：提示里写入 captions 与 box 列表，不写入像素。合成对话的空间关系来自框坐标，颜色与纹理若标题没写就会缺。这解释了初代 LLaVA 在细 OCR 与「标题未提及的物体」上的失败模式。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="三种指令-对应三种对话技能" tabindex="-1">三种指令，对应三种对话技能 <a class="header-anchor" href="#三种指令-对应三种对话技能" aria-label="Permalink to &quot;三种指令，对应三种对话技能&quot;">​</a></h3><p>对每张 COCO 图，提示 GPT-4 产出：（1）<strong>对话</strong>：短轮问答，覆盖物体、计数、相对位置；（2）<strong>详细描述</strong>：一段完整场景叙述；（3）<strong>复杂推理</strong>：超出图中直接可见、需要常识或多步的问题。三者比例组成 158K。模板把图像 token 放在约定占位符，角色分隔与 Vicuna 一致。没有这一步，模型只会接 CC 标题电缆，不会列清单、不会拒绝、不会跟「请用一句话」。</p><p>ScienceQA 作为例外：该基准自带讲义式问答，LLaVA 在其上做针对性微调，报告当时达到约 90.92% 的准确率，用来说明「浅桥 + 指令数据」也能打结构化多模态考试，而不是只能闲聊。主模型仍是通用视觉助手叙事；不要把 ScienceQA 专调检查点与通用 158K 检查点混成一个权重。</p>',13)),(e(),s(L,null,{default:r(()=>[p(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20COCO%5B%22COCO%20%E6%A0%87%E9%A2%98%20%2F%20%E6%A1%86%20%2F%20%E7%B1%BB%22%5D%20--%3E%20GPT%5B%22GPT-4%20%E7%BA%AF%E6%96%87%E6%9C%AC%E6%95%99%E5%B8%88%22%5D%0A%20%20GPT%20--%3E%20D158%5B%22158K%20%E5%AF%B9%E8%AF%9D%20%2F%20%E6%8F%8F%E8%BF%B0%20%2F%20%E6%8E%A8%E7%90%86%22%5D%0A%20%20CC%5B%22CC-595K%22%5D%20--%3E%20P1%5B%22%E9%98%B6%E6%AE%B51%EF%BC%9A%E5%8F%AA%E8%AE%AD%E7%BA%BF%E6%80%A7%20W%22%5D%0A%20%20CLIP%5B%22%E5%86%BB%E7%BB%93%20CLIP%20ViT-L%2F14%22%5D%20--%3E%20W%5B%22%E7%BA%BF%E6%80%A7%E6%8A%95%E5%BD%B1%22%5D%0A%20%20W%20--%3E%20VIC%5B%22Vicuna%22%5D%0A%20%20D158%20--%3E%20P2%5B%22%E9%98%B6%E6%AE%B52%EF%BC%9A%E8%AE%AD%20W%20%2B%20LLM%22%5D%0A%20%20P1%20--%3E%20P2%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=n('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>浅投影能工作，前提是 CLIP 对比学习已经让 \\(Z_v\\) 对语言可检索；\\(W\\) 只需把坐标系转到 Vicuna 的嵌入尺度。第一阶段的标题生成把 \\(H_v\\) 拉进「可以续写英文句子」的区域；第二阶段才把 Vicuna 的指令跟随条件在这些槽位上。因为没有 query 瓶颈，空间布局以 raster 顺序留在序列里，计数与左右关系有机会被自注意力读出来——机会不等于监督：158K 里这类问题的密度决定了能读多准。</p><p>相对 InstructBLIP，视觉特征<strong>不</strong>随问题改变：同一张图的前缀可缓存，多轮对话只追加文本。相对 Flamingo，不插入门控交叉注意力，部署就是一次标准 Decoder 前向。代价是窗口被 \\(N_{\\mathrm{vis}}\\) 永久占用，高分辨率在初代无解。</p><p><span class="marginnote">LLaVA-Bench（In-the-Wild）用非常规图与 GPT-4 打分，是论文推动的对话评测，不是 VQAv2 准确率。引用「接近 GPT-4」必须写 LLaVA-Bench 设定，且教师与裁判都是 GPT-4 时存在自偏好风险。</span></p><h3 id="和「再训一个视觉桥」的算力对比" tabindex="-1">和「再训一个视觉桥」的算力对比 <a class="header-anchor" href="#和「再训一个视觉桥」的算力对比" aria-label="Permalink to &quot;和「再训一个视觉桥」的算力对比&quot;">​</a></h3><p>Q-Former 第一阶段要在图文对上跑三个损失；Flamingo 要在交错网页上训插入层。LLaVA 对齐阶段只训一个矩阵，指令阶段在 8×A100 量级即可做完 13B。论文的方法论主张因此是<strong>数据中心</strong>：架构减到不能再减，把预算留给 GPT-4 合成与公开图文过滤。这为 1.5 节「学术 VQA + 格式提示也能涨分」埋下伏笔——一旦浅桥成立，涨点优先来自数据，而不是来自更深的连接器。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>224 分辨率、冻 ViT、线性层、158K 合成，四条边界一起限制了 OCR、图表与非 COCO 域。GPT-4 教师会把语言模型的偏见写进对话（性别、地域、过度自信）。CC-595K 过滤偏向自然照片，截图与扫描件是域外。Vicuna 基于 LLaMA，权重许可不是 Apache。不要把初代写成已经支持 AnyRes 或多图：那是 NeXT / OneVision。</p><p>部署时图像占位符、起止 token、与训练不一致会导致投影槽错位，表现为「能聊天但像没看见图」。量化应保护视觉前缀：每个 patch 上的误差会累积成认错物体，而不是 LLM 突然不会说话。ScienceQA 数字不可当作通用 VQA SOTA。初代没有系统对比「线性 vs MLP」——那是 1.5 的消融。若要用初代权重做文档问答，应预期失败并升级到 1.5 的 336 或 NeXT 的切格，而不是把线性层加宽当成补分辨率。</p><p><span class="marginnote">论文全称 <em>Visual Instruction Tuning</em>。口头说 LLaVA 时请钉 2304.08485，以免与 LLaVA-1.5（2310.03744）、NeXT 博客、OneVision（2408.03326）抢同一句「LLaVA 证明了浅桥」。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>初代 LLaVA：CLIP ViT-L/14 + 线性投影 + Vicuna；两阶段先对齐再视觉指令微调。</li><li>指令数据约 158K，由 GPT-4 根据 COCO 符号标注合成对话、描述与推理。</li><li>不压缩视觉长度、不改 LLM 注意力形状；能力上限受 224 分辨率与合成教师约束。</li><li>ScienceQA 专调与 LLaVA-Bench 是两条不同评测，不要混用。</li><li>出处：Liu 等，<em>Visual Instruction Tuning</em>（LLaVA），NeurIPS 2023，arXiv:2304.08485。</li></ul>',12))])}const T=i(A,[["render",h]]);export{E as __pageData,T as default};
